export function categoriesForSegments(segmentIds: string[]): { segment: Segment; category: EquipmentCategory }[] {
  return SEGMENTS.filter((s) => segmentIds.includes(s.id)).flatMap((segment) =>
    segment.categories.map((category) => ({ segment, category })),
  );
}

